import StatisticsCards from '@/components/cards/StatisticsCards';
import GroupIcon from '@/components/icons/user/GroupIcon';
import MinusUserIcon from '@/components/icons/user/MinusUserIcon';
import TwoUsersIcon from '@/components/icons/user/TwoUsersIcon';
import UserRemoveIcon from '@/components/icons/UserRemoveIcon';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { Card } from '@/types/statistics';
import { useEffect, useState } from 'react';

type Counts = { total: number; approved: number; rejected: number; pending: number };

async function loanRequestCounts(): Promise<Counts> {
    const base = { page: 1, pageSize: 1 } as const;
    const [all, approved, rejected, pending] = await Promise.all([
        apiGet({ endpoint: endpoints.loan.list, queryParams: { ...base } }),
        apiGet({ endpoint: endpoints.loan.list, queryParams: { ...base, status: 'approved' } }),
        apiGet({ endpoint: endpoints.loan.list, queryParams: { ...base, status: 'rejected' } }),
        apiGet({ endpoint: endpoints.loan.list, queryParams: { ...base, status: 'pending' } }),
    ]);
    const t = (r: typeof all) => r.data.data?.pagination?.total ?? 0;
    return { total: t(all), approved: t(approved), rejected: t(rejected), pending: t(pending) };
}

export default function LoansRequestsStatistics() {
    const [stats, setStats] = useState<Counts | null>(null);

    useEffect(() => {
        let cancelled = false;
        (async () => {
            try {
                const c = await loanRequestCounts();
                if (!cancelled) setStats(c);
            } catch {
                if (!cancelled) setStats(null);
            }
        })();
        return () => {
            cancelled = true;
        };
    }, []);

    const cards: Card[] = [
        { text: 'إجمالي طلبات القروض', num: stats?.total, percent: 0, icon: <GroupIcon /> },
        { text: 'القروض المقبوله', num: stats?.approved, percent: 0, icon: <TwoUsersIcon /> },
        { text: 'القروض المرفوضه', num: stats?.rejected, percent: 0, icon: <MinusUserIcon /> },
        { text: 'القروض المعلقة', num: stats?.pending, percent: 0, icon: <UserRemoveIcon /> },
    ];

    return <StatisticsCards cards={cards} numJustifyStart={true} />;
}
