import StatisticsCards from '@/components/cards/StatisticsCards';
import GroupIcon from '@/components/icons/user/GroupIcon';
import TwoUsersIcon from '@/components/icons/user/TwoUsersIcon';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { Card } from '@/types/statistics';
import { useEffect, useState } from 'react';

type Counts = { total: number; pending: number };

async function beneficiaryCounts(): Promise<Counts> {
    const base = { page: 1, pageSize: 1 } as const;
    const [all, pending] = await Promise.all([
        apiGet({ endpoint: endpoints.insuranceRelatives.paginate, queryParams: { ...base } }),
        apiGet({ endpoint: endpoints.insuranceRelatives.paginate, queryParams: { ...base, status: 'pending' } }),
    ]);
    const t = (r: typeof all) => r.data.data?.pagination?.total ?? 0;
    return { total: t(all), pending: t(pending) };
}

export default function RequestsToAddBeneficiariesStatistics() {
    const [stats, setStats] = useState<Counts | null>(null);

    useEffect(() => {
        let cancelled = false;
        (async () => {
            try {
                const c = await beneficiaryCounts();
                if (!cancelled) setStats(c);
            } catch {
                if (!cancelled) setStats(null);
            }
        })();
        return () => {
            cancelled = true;
        };
    }, []);

    const cards: Card[] = [
        { text: 'إجمالي طلبات المستفيدين', num: stats?.total, percent: 0, icon: <GroupIcon /> },
        { text: 'طلبات قيد المراجعة', num: stats?.pending, percent: 0, icon: <TwoUsersIcon /> },
    ];

    return <StatisticsCards cards={cards} numJustifyStart={true} />;
}
