import { cn } from '@/lib/utils';
import { useEffect, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import RequestsList from './requestsList/RequestsList';
import RequestsToAddBeneficiaries from './RequestsToAddBeneficiaries/RequestsToAddBeneficiaries';
import LoansRequest from './loansRequests/LoansRequests';

export default function SelectabelContent() {
    const [searchParams, setSearchParams] = useSearchParams();
    const loansParam = searchParams.get('loans');
    const [activeSection, setActiveSection] = useState(() => (loansParam ? 3 : 1));

    useEffect(() => {
        if (loansParam) {
            setActiveSection(3);
        }
    }, [loansParam]);

    const handleSelect = (value: number) => {
        setActiveSection(value);
        setSearchParams(
            (prev) => {
                const next = new URLSearchParams(prev);
                if (value === 3) {
                    next.set('loans', '1');
                } else {
                    next.delete('loans');
                }
                return next;
            },
            { replace: true },
        );
    };

    return (
        <div className="w-full mt-6">
            <div className="w-full flex flex-row items-center gap-[1px]">
                <button
                    type="button"
                    onClick={() => handleSelect(1)}
                    className={cn(
                        'w-full transition-colors text-sm sm:text-base py-3 px-2 text-white-blue-50 font-bold leading-snug tracking-normal rounded-s-lg text-center whitespace-normal',
                        {
                            'bg-primery-blue-700': activeSection === 1,
                            'bg-primery-blue-400': activeSection !== 1,
                        },
                    )}
                >
                    طلبات الخدمات
                </button>
                <button
                    type="button"
                    onClick={() => handleSelect(2)}
                    className={cn(
                        'w-full transition-colors text-sm sm:text-base py-3 px-2 text-white-blue-50 font-bold leading-snug tracking-normal text-center whitespace-normal',
                        {
                            'bg-primery-blue-700': activeSection === 2,
                            'bg-primery-blue-400': activeSection !== 2,
                        },
                    )}
                >
                    مستفيدو التأمين
                </button>
                <button
                    type="button"
                    onClick={() => handleSelect(3)}
                    className={cn(
                        'w-full transition-colors text-sm sm:text-base py-3 px-2 text-white-blue-50 font-bold leading-snug tracking-normal text-center whitespace-normal',
                        {
                            'bg-primery-blue-700': activeSection === 3,
                            'bg-primery-blue-400': activeSection !== 3,
                        },
                    )}
                >
                    طلبات السلف والقروض
                </button>
            </div>
            {activeSection === 1 && <RequestsList />}
            {activeSection === 2 && <RequestsToAddBeneficiaries />}
            {activeSection === 3 && <LoansRequest />}
        </div>
    );
}
